import mathfrom .units import to_unitdef _as_number(value):    """Coerce a cell to float. Returns None when it isn't numeric."""    if value is None:        return None    if isinstance(value, bool):        return None    if isinstance(value, (int, float)):        return None if (isinstance(value, float) and math.isnan(value)) else float(value)    s = str(value).strip()    if not s or s.lower() in {"na", "n/a", "nan", "none", "null", "-", "--"}:        return None    s = s.replace(",", "")    # Tolerate a trailing unit, e.g. "48.2 MPa" or "6.1%"    cleaned = []    for ch in s:        if ch.isdigit() or ch in ".-+eE":            cleaned.append(ch)        elif cleaned:            break    try:        return float("".join(cleaned))    except ValueError:        return Nonedef eval_check(row: dict, check: dict, units_map: dict):    """Evaluate a single check against a specimen row.    Returns (status, rationale) where status is PASS, FAIL, MISSING or ERROR.    """    metric = check["metric"]    raw = row.get(metric, None)    op = check["op"]    note = check.get("note", "")    if raw is None or (isinstance(raw, float) and math.isnan(raw)):        return "MISSING", f"{metric} missing"    if isinstance(raw, str) and not raw.strip():        return "MISSING", f"{metric} missing"    # in_set compares text, so it needs no numeric conversion.    if op == "in_set":        allowed = set(map(str, check.get("set", [])))        ok = str(raw).strip() in allowed        status = "PASS" if ok else "FAIL"        return status, (f"{metric} in_set ({note}) | measured={raw} | "                        f"allowed={sorted(allowed)}")    val = _as_number(raw)    if val is None:        return "ERROR", f"{metric} is not numeric | measured={raw}"    from_u = units_map.get(metric)    target_u = check.get("unit", from_u)    if from_u and target_u and from_u != target_u:        converted = None        try:            converted = to_unit(val, from_u, target_u)        except Exception:            converted = None        if converted is None:            return "ERROR", f"{metric} unit conversion failed: {from_u} to {target_u}"        val = float(converted)    try:        if op == ">=":            threshold = _as_number(check.get("value"))            if threshold is None:                return "ERROR", f"{metric} threshold is not numeric"            margin = val - threshold            ok = val >= threshold        elif op == "<=":            threshold = _as_number(check.get("value"))            if threshold is None:                return "ERROR", f"{metric} threshold is not numeric"            margin = threshold - val            ok = val <= threshold        elif op == "between":            lo = _as_number(check.get("min"))            hi = _as_number(check.get("max"))            if lo is None or hi is None:                return "ERROR", f"{metric} range is not numeric"            margin = min(val - lo, hi - val)            ok = lo <= val <= hi        else:            return "ERROR", f"{metric} unknown op {op}"    except TypeError:        return "ERROR", f"{metric} could not be compared"    status = "PASS" if ok else "FAIL"    margin_txt = "" if (margin is None or math.isnan(margin)) else round(margin, 3)    unit_txt = f" {target_u}" if target_u else ""    rationale = (f"{metric} {op} ({note}) | measured={val}{unit_txt} | "                 f"margin={margin_txt}")    return status, rationale